SQL_DOC.P_SQL:
SELECT SO06.IF_ORDR_NO AS LEGACY_PO_NO , SO06.IF_ORDR_SEQ AS LEGACY_PO_SEQ , SO06.GDS_CD AS ITEM_NO , (SELECT MAX(DLVRY_PLAN_DATE) FROM KEPCON.KEPWMGI03 WHERE CSTMR_ID = SO06.CSTMR_ID AND ORDR_NO = SO06.ORDR_NO AND ORDR_SEQ= SO06.ORDR_SEQ) AS DS_DATE
, substr(SO06.SPPLR_ID,1,10) AS AGENT , SO06.ORDR_QTY AS ITEM_QTY , F_GET_ORDER_TRACKING(SO06.CSTMR_ID,SO06.ORDR_NO,SO06.ORDR_SEQ,'DO_QTY') AS DO_QTY , F_GET_ORDER_TRACKING(SO06.CSTMR_ID,SO06.ORDR_NO,SO06.ORDR_SEQ,'IV_QTY') AS IV_QTY , F_GET_ORDER_TRACKING(SO06.CSTMR_ID,SO06.ORDR_NO,SO06.ORDR_SEQ,'DI_QTY') AS DI_QTY , F_GET_ORDER_TRACKING(SO06.CSTMR_ID,SO06.ORDR_NO,SO06.ORDR_SEQ,'GR_QTY') AS GR_QTY , SUBSTR(SO06.CSTMR_ID,1,10) AS PLANT , SO06.ORDR_NO , SO06.ORDR_SEQ , DECODE(F_GET_ORDER_TRACKING(SO06.CSTMR_ID,SO06.ORDR_NO,SO06.ORDR_SEQ,'STATUS'), '주문','1', '수주접수','2', '부분납품서','3', '납품서완료','3', '배송완료','4', '부분배송','4', '입고완료','4', '부분입고','4','9') AS ORDER_FLAG , GETALANCINFO(SO06.SPPLR_ID,'ALANC_NM') AS AGENT_NAME , GETALANCINFO(SO06.SPPLR_ID,'RPRSNT_PHON_NO') AS AGENT_TEL , TO_CHAR(SYSDATE, 'YYYYMMDD') AS SYS_DATE , TO_CHAR(SYSDATE, 'HH24MISS') AS SYS_TIME FROM KEPCON.KEPMPSO06 SO06 WHERE SO06.CSTMR_ID = '$G_RS.CSTMR_ID$' AND SO06.ORDR_NO = '$G_RS.ORDR_NO$' AND SO06.ORDR_SEQ = $G_RS.ORDR_SEQ$ ORDER BY CSTMR_ID, ORDR_NO, ORDR_SEQ
DECLARE BEGIN
CASE '$G_RS.DOC_NAME$' WHEN '01_PO' THEN UPDATE KEPCON.KEPMPSO06 SO06 SET SND_CHK = 'Y' , SND_DATM= SYSDATE WHERE CSTMR_ID = '$G_RS.CSTMR_ID$' AND ORDR_NO = '$G_RS.KEY_1$' AND ORDR_SEQ= $G_RS.KEY_2$; WHEN '02_RS' THEN UPDATE KEPCON.KEPMPRS02 SET SND_CHK = 'Y' , SND_DATM= SYSDATE WHERE CSTMR_ID = '$G_RS.CSTMR_ID$' AND DLVRY_PLAN_NO = '$G_RS.KEY_1$' AND DLVRY_PLAN_SEQ= $G_RS.KEY_2$; WHEN '03_IV' THEN IF '$G_RS.IS_HEAD$' = 'Y' THEN UPDATE KEPCON.KEPMPSV01 SET SND_CHK = 'Y' , SND_DATM= SYSDATE WHERE CSTMR_ID = '$G_RS.CSTMR_ID$' AND DEAL_STTMN_NO = '$G_RS.KEY_1$'; END IF; UPDATE KEPCON.KEPMPSV02 SET SND_CHK = 'Y' , SND_DATM= SYSDATE WHERE DEAL_STTMN_NO = '$G_RS.KEY_1$' AND DEAL_STTMN_SEQ= $G_RS.KEY_2$; WHEN '04_DI' THEN UPDATE KEPCON.KEPWMDE02 DE02 SET SND_CHK = 'Y' ,SND_DATM=SYSDATE WHERE SHP_NO = '$G_RS.KEY_1$' AND SHP_SEQ= $G_RS.KEY_2$; ELSE NULL; END CASE; END;
DECLARE BEGIN
CASE '$G_RS.DOC_NAME$' WHEN '01_PO' THEN UPDATE KEPCON.KEPMPSO06 SO06 SET SND_CHK = 'E' , SND_DATM= SYSDATE WHERE CSTMR_ID = '$G_RS.CSTMR_ID$' AND ORDR_NO = '$G_RS.KEY_1$' AND ORDR_SEQ= $G_RS.KEY_2$; WHEN '02_RS' THEN UPDATE KEPCON.KEPMPRS02 SET SND_CHK = 'E' , SND_DATM= SYSDATE WHERE CSTMR_ID = '$G_RS.CSTMR_ID$' AND DLVRY_PLAN_NO = '$G_RS.KEY_1$' AND DLVRY_PLAN_SEQ= $G_RS.KEY_2$; WHEN '03_IV' THEN IF '$G_RS.IS_HEAD$' = 'Y' THEN UPDATE KEPCON.KEPMPSV01 SET SND_CHK = 'E' , SND_DATM= SYSDATE WHERE CSTMR_ID = '$G_RS.CSTMR_ID$' AND DEAL_STTMN_NO = '$G_RS.KEY_1$'; END IF; UPDATE KEPCON.KEPMPSV02 SET SND_CHK = 'E' , SND_DATM= SYSDATE WHERE DEAL_STTMN_NO = '$G_RS.KEY_1$' AND DEAL_STTMN_SEQ= $G_RS.KEY_2$; WHEN '04_DI' THEN UPDATE KEPCON.KEPWMDE02 DE02 SET SND_CHK = 'E' ,SND_DATM=SYSDATE WHERE SHP_NO = '$G_RS.KEY_1$' AND SHP_SEQ= $G_RS.KEY_2$; ELSE NULL; END CASE; END;
